cat > src/core/loyalty.ts <<'EOF'
import { formatMoney } from "./money.ts";
import type { Customer } from "./price.ts";

export const LOYALTY_MIN_ORDERS = 5;
export const LOYALTY_PERCENT = 10;

export interface LoyaltyResult {
  total: number;
  message: string;
}

/** A customer with more than five orders gets ten percent off. Amounts are in cents. */
export function applyLoyaltyDiscount(customer: Customer, totalCents: number): LoyaltyResult {
  if (customer.orders <= LOYALTY_MIN_ORDERS) {
    return { total: totalCents, message: "No loyalty discount" };
  }
  const saved = Math.round((totalCents * LOYALTY_PERCENT) / 100);
  return {
    total: totalCents - saved,
    message: `Loyalty discount: you saved ${formatMoney(saved)}`,
  };
}
EOF
cat > tests/loyalty.test.ts <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";
import { applyLoyaltyDiscount } from "../src/core/loyalty.ts";

test("more than five orders gets ten percent off", () => {
  const result = applyLoyaltyDiscount({ id: "a", orders: 6 }, 2550);
  assert.equal(result.total, 2295);
  assert.equal(result.message, "Loyalty discount: you saved $2.55");
});

test("five orders or fewer pays full price", () => {
  const result = applyLoyaltyDiscount({ id: "a", orders: 5 }, 2550);
  assert.equal(result.total, 2550);
});
EOF
npm test 2>&1 | tail -12; lawcheck check

